/* ❌ OLD: Framework-emulated scoping appends a generated attribute or
   hash to every selector. It works, but the compiled CSS is noisy,
   specificity is inflated by the extra attribute, and it is opaque to
   developers reading the output. */

.card[data-v-abc123] .title[data-v-abc123] {
  font-weight: bold; /* ❌ OLD: readability suffers; specificity inflated */
}

/* The hash must be unique per build, selectors grow, and debugging
   the real cascade in devtools shows hashed selectors instead of the
   author intent. */

/* ✅ NEW: @scope scopes rules to the .card subtree with author-readable
   selectors, plus the cascade proximity rule: an inner scope wins over
   an outer one at equal specificity. */

@scope (.card) {
  /* ✅ NEW: :scope refers to the scope root (.card) */
  :scope {
    border: 1px solid;
  }
  .title {
    font-weight: bold; /* ✅ NEW: only matches inside a .card */
  }
}

/* No hashes, no inflated specificity; the scope boundary is explicit
   and the rules read like the component they style. */
